// Carga el catálogo en DB.materiales si todavía está vacío (primer uso)
function cargarCatalogoInicial(){
  if (typeof DB === 'undefined') return;
  if (DB.materiales && DB.materiales.length > 0) return; // ya tiene datos, no pisar
  DB.materiales = MATERIALES_CATALOGO.map(m => ({
    id: uid(), nombre:m.nombre, categoria:m.categoria, marca:m.marca,
    modelo:m.modelo, caract:m.caract, proveedor:m.prov, obs:m.obs, fecha:hoy()
  }));
  guardarDB('materiales');
}
